sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    //MSSTRUSTES-247
    try {
        var mapping = {
            'CSEM_CAT_A_B_OTHERS': 'OTHER',
            'CSEM_SANCTIONS': 'OTHER/SANCTIONED',
            'ER_VC_REGULAR_BTW_20_50': 'OTHER/SIP_SIE',
            'FHRC': 'PROHIBIT_COUNTRY',
            'SVC': 'OTHER/SIP_SIE',
            'HR_PEP': 'PEP',
            'HR_PEP_O': 'PEP',
            'HR_PEP_S': 'PEP/SANCTIONED',
            'HR_PEP_T': 'PEP/SUSPECT_TERRORIST',
            'OTHERS': 'OTHER',
            'PEP': 'PEP',
            'PEP_S': 'PEP/SANCTIONED',
            'PEP_T': 'PEP/SUSPECT_TERRORIST',
            'SANCTION_COUNTRIES_CLIENTS': 'SANCTIONED',
            'SAR': 'OTHER/SIP_SIE',
            'REGULATORY_ENFORCEMENT': 'SANCTIONED',
            'TERRORISTS': 'SUSPECT_TERRORIST',
            'TM': 'OTHER/SIP_SIE',
            'UAR': 'OTHER/SIP_SIE',
            'ER_VC_REGULAR_OVER_50': 'OTHER/SIP_SIE',
            'CSEM_CAT_C_E': 'OTHER',
            'SCC02': 'SIP-SIE',
            'SCC03': 'SIP-SIE',
            'SCC04': 'SIP-SIE',
            'SCC05': 'SIP-SIE',
            'SCC06': 'SIP-SIE',
            'SCC07': 'SIP-SIE',
            'SCC08': 'SIP-SIE',
            'SCC09': 'SIP-SIE',
            'SCC10': 'SIP-SIE',
            'SCC11': 'SIP-SIE',
            'SCC12': 'SIP-SIE',
            'SCC20': 'SIP-SIE',
			'blank': 'Blank( show no value)'
        };

        var flag = current.sensitive_flag_aml_type_1_er_risk + '';
        if (mapping[flag]) {
            current.empf_aml_type_1_2_3_proposed_er_risk = mapping[flag];
        }
    } catch (e) {
        gs.error('Error in Mapping Sensitive Flag to AML Type Business Rule: ' + e.message);
    }

})(current, previous);
